// ---- Ajudantes de cartoon (iguais em todos os orbs da serie; edite a vontade) ----
const TINTA = "#1B1B2F";
const fala = (s) => s === "speaking", ouve = (s) => s === "listening", erro = (s) => s === "error";
const ocupado = (s) => s === "connecting" || s === "starting";

// Preenche com contorno escuro, no estilo de desenho animado
function forma(ctx, path, fill, w = 3.5, line = TINTA) {
  ctx.fillStyle = fill;
  ctx.fill(path);
  if (w) { ctx.strokeStyle = line; ctx.lineWidth = w; ctx.lineJoin = "round"; ctx.stroke(path); }
}
function oval(x, y, rx, ry, rot = 0) { const p = new Path2D(); p.ellipse(x, y, rx, ry, rot, 0, orb.TAU); return p; }
// Gradiente de volume: luz em cima a esquerda
function luz(ctx, x, y, r, c0, c1) {
  const g = ctx.createRadialGradient(x - r * 0.35, y - r * 0.4, r * 0.05, x, y, r * 1.15);
  g.addColorStop(0, c0); g.addColorStop(1, c1);
  return g;
}
// Rosto: olhos e boca mudam com o estado.
// f: x, y, gap, r, boca (distancia ate a boca; null = sem boca), bocaW, olho (cor), tinta, brilho,
//    bochecha (cor; null = sem), um (so um olho), olhos (false = so a boca)
function rosto(ctx, t, state, f = {}) {
  const x = f.x ?? 96, y = f.y ?? 96, gap = f.gap ?? 22, r = f.r ?? 9;
  const tinta = f.tinta ?? TINTA, olho = f.olho ?? tinta, brilho = f.brilho ?? "#FFFFFF";
  const pisca = state === "idle" && t > 0.86 && t < 0.94;
  const olhar = state === "connecting" ? r * 0.45 * orb.wave(t) : 0;
  const s = state === "listening" ? 1.25 : 1;
  ctx.lineCap = "round"; ctx.lineJoin = "round"; ctx.strokeStyle = tinta; ctx.lineWidth = Math.max(2.5, r * 0.32);
  for (const k of (f.olhos === false ? [] : f.um ? [0] : [-1, 1])) {
    const ex = x + k * gap, ey = y;
    ctx.beginPath();
    if (state === "error") {
      const d = r * 0.75;
      ctx.moveTo(ex - d, ey - d); ctx.lineTo(ex + d, ey + d); ctx.moveTo(ex + d, ey - d); ctx.lineTo(ex - d, ey + d); ctx.stroke();
    } else if (pisca || state === "starting") {
      ctx.arc(ex, ey - r * 0.2, r * 0.8, 0.15 * Math.PI, 0.85 * Math.PI); ctx.stroke();
    } else if (state === "speaking") {
      ctx.arc(ex, ey + r * 0.35, r * 0.8, 1.15 * Math.PI, 1.85 * Math.PI); ctx.stroke();
    } else {
      ctx.ellipse(ex, ey, r * s, r * 1.15 * s, 0, 0, orb.TAU); ctx.fillStyle = olho; ctx.fill();
      orb.circle(ctx, ex - r * 0.3 * s + olhar, ey - r * 0.4 * s, r * 0.36 * s, brilho);
      ctx.globalAlpha = 0.7; orb.circle(ctx, ex + r * 0.35 * s + olhar, ey + r * 0.35 * s, r * 0.15 * s, brilho); ctx.globalAlpha = 1;
    }
  }
  if (f.bochecha !== null) {
    ctx.globalAlpha = 0.35;
    for (const k of [-1, 1]) orb.circle(ctx, x + k * (gap + r * 0.7), y + r * 1.5, r * 0.75, f.bochecha ?? "#FF8FB3");
    ctx.globalAlpha = 1;
  }
  if (f.boca === null) return;
  const my = y + (f.boca ?? r * 2.3), w = f.bocaW ?? r * 1.1;
  ctx.strokeStyle = tinta; ctx.fillStyle = "#5A1730"; ctx.beginPath();
  if (state === "speaking") { ctx.ellipse(x, my + 2, w * 0.85, 2 + w * 0.7 * orb.ping(t, 4), 0, 0, orb.TAU); ctx.fill(); ctx.stroke(); }
  else if (state === "listening") { ctx.ellipse(x, my + 2, w * 0.35, w * 0.45, 0, 0, orb.TAU); ctx.fill(); ctx.stroke(); }
  else if (state === "error") { ctx.arc(x, my + w, w * 0.9, 1.2 * Math.PI, 1.8 * Math.PI); ctx.stroke(); }
  else if (state === "connecting") { ctx.moveTo(x - w * 0.6, my + 2); ctx.lineTo(x + w * 0.6, my + 2); ctx.stroke(); }
  else { ctx.arc(x, my - w * 0.3, w, 0.2 * Math.PI, 0.8 * Math.PI); ctx.stroke(); }
}
// Flutua de leve (mais rapido falando)
function flutua(ctx, t, state, amp = 3) { ctx.translate(0, orb.wave(t, fala(state) ? 2 : 1) * amp); }
// ---------------------------------------------------------------------------------

function draw(ctx, t, state) {
  flutua(ctx, t, state, 2);
  const orelha = ouve(state) ? -6 : 0;
  for (const k of [-1, 1]) {
    const p = new Path2D();
    p.moveTo(96 + k * 20, 66); p.lineTo(96 + k * 48, 26 + orelha); p.lineTo(96 + k * 54, 76); p.closePath();
    forma(ctx, p, "#F39A3D");
    const q = new Path2D();
    q.moveTo(96 + k * 30, 64); q.lineTo(96 + k * 46, 38 + orelha); q.lineTo(96 + k * 48, 68); q.closePath();
    forma(ctx, q, "#FFB3C8", 0);
  }
  forma(ctx, oval(96, 106, 62, 52), luz(ctx, 96, 106, 62, "#FFD08A", "#E07A1F"));
  // listras na testa
  ctx.strokeStyle = "#B8561A"; ctx.lineWidth = 4; ctx.lineCap = "round";
  for (const dx of [-12, 0, 12]) { ctx.beginPath(); ctx.moveTo(96 + dx, 58); ctx.lineTo(96 + dx * 0.8, 70); ctx.stroke(); }
  forma(ctx, oval(96, 136, 30, 18), "#FFF3E0", 0);
  rosto(ctx, t, state, { y: 102, gap: 24, r: 9, boca: 30, bocaW: 8 });
  // nariz e bigodes
  const nariz = new Path2D(); nariz.moveTo(90, 120); nariz.lineTo(102, 120); nariz.lineTo(96, 127); nariz.closePath();
  forma(ctx, nariz, "#FF7FA0", 2);
  ctx.strokeStyle = TINTA; ctx.lineWidth = 2;
  for (const k of [-1, 1]) for (const dy of [-4, 4]) {
    ctx.beginPath(); ctx.moveTo(96 + k * 30, 128 + dy); ctx.lineTo(96 + k * 58, 124 + dy * 2.2 + orb.wave(t, 2) * 1.5); ctx.stroke();
  }
}
